package cz.nikinkawow;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.text.method.LinkMovementMethod;
import java.net.*;import java.io.*;import java.util.*;import javax.xml.parsers.*;import org.w3c.dom.*;
public class MainActivity extends Activity {
 LinearLayout root; TextView status; final String[] interests={"Nightwish Tarja symphonic metal","Washington Poe M W Craven knihy","muzikál Rebecca divadlo","Pán prstenů Tolkien","Skotsko polární záře","fantasy knihy novinky","orchideje botanika","historie záhady archeologie","koně zajímavosti","filmové fantasy novinky"};
 ArrayList<Story> stories=new ArrayList<>(); Set<String> liked=new HashSet<>(); int index=0;
 static class Story {String title,url,category; Story(String t,String u,String c){title=t;url=u;category=c;}}
 public void onCreate(Bundle b){super.onCreate(b);liked.addAll(getPreferences(0).getStringSet("liked",new HashSet<>()));show();refresh();}
 TextView text(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(Color.rgb(45,29,61));v.setPadding(14,16,14,16);return v;}
 void show(){ScrollView scroll=new ScrollView(this);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(22,35,22,20);root.setBackgroundColor(Color.rgb(250,244,252));scroll.addView(root);setContentView(scroll);root.addView(text("💜 Nikinka WOW",28));root.addView(text("Každý den něco, o čem se dá povídat.",16));status=text("Načítám novinky…",15);root.addView(status);Button refresh=new Button(this);refresh.setText("🔎 Hledat čerstvé novinky");refresh.setOnClickListener(v->refresh());root.addView(refresh);Button surprise=new Button(this);surprise.setText("🎲 Překvap mě");surprise.setOnClickListener(v->{if(!stories.isEmpty()){index=new Random().nextInt(stories.size());render();}});root.addView(surprise);}
 void refresh(){status.setText("Prohledávám internet…");new Thread(()->{ArrayList<Story> found=new ArrayList<>();for(String q:interests){try{String u="https://news.google.com/rss/search?q="+URLEncoder.encode(q+" when:14d","UTF-8")+"&hl=cs&gl=CZ&ceid=CZ:cs";HttpURLConnection c=(HttpURLConnection)new URL(u).openConnection();c.setConnectTimeout(9000);c.setReadTimeout(9000);c.setRequestProperty("User-Agent","NikinkaWOW/0.1");try(InputStream in=c.getInputStream()){DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);Document doc=f.newDocumentBuilder().parse(in);NodeList items=doc.getElementsByTagName("item");for(int j=0;j<Math.min(5,items.getLength());j++){Element e=(Element)items.item(j);String title=e.getElementsByTagName("title").item(0).getTextContent();String link=e.getElementsByTagName("link").item(0).getTextContent();if(!title.isEmpty()&&link.startsWith("https://"))found.add(new Story(title,link,q));}}c.disconnect();}catch(Exception ignored){}}Collections.shuffle(found);runOnUiThread(()->{stories=found;index=0;status.setText(found.isEmpty()?"Novinky se nepodařilo načíst. Zkus připojení a obnovit.":"Nalezeno "+found.size()+" témat. Zprávy ověřuj v původním zdroji.");render();});}).start();}
 void render(){while(root.getChildCount()>5)root.removeViewAt(5);if(stories.isEmpty())return;Story s=stories.get(index);root.addView(text("✨ Dnešní inspirace • "+s.category,17));root.addView(text(s.title,23));root.addView(text("Zeptej se Niki: „Viděla jsi tuhle novinku? Co si o tom myslíš?“\n\nNavazující otázka: „Co tě na tom nejvíc zaujalo?“",16));Button source=new Button(this);source.setText("Otevřít původní zprávu");source.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse(s.url))));root.addView(source);Button like=new Button(this);like.setText(liked.contains(s.category)?"💜 Oblíbené téma":"♡ To by Niki bavilo");like.setOnClickListener(v->{liked.add(s.category);getPreferences(0).edit().putStringSet("liked",new HashSet<>(liked)).apply();render();});root.addView(like);Button next=new Button(this);next.setText("Další téma →");next.setOnClickListener(v->{index=(index+1)%stories.size();render();});root.addView(next);}
}
